// src/components/SkillsTicker.jsx
import React from 'react';
import { motion } from 'framer-motion';

const skills = [
  'Adobe Creative Suite', 'Community Outreach',
  'Convolutional Neural Networks', 'Educational Services',
  'Java', 'Linux', 'Mentorship',
  'Robotics', 'Team Management',
  'Technical Leadership', 'Web Design'
];

export default function SkillsTicker({ theme }) {
  // duplicate so it loops seamlessly
  const looped = [...skills, ...skills];

  return (
    <section id="skills" className="py-0">
      <h2
        className={`
          text-2xl font-bold mb-6
          ${theme === 'dark' ? 'text-yellow-400' : 'text-blue-800'}
        `}
      >
        Technical Skills
      </h2>

      <div className="overflow-hidden whitespace-nowrap py-3">
        <motion.div
          className="inline-flex space-x-12"
          animate={{ x: ['0%', '-50%'] }}
          transition={{
            x: {
              repeat: Infinity,
              repeatType: 'loop',
              duration: 35,
              ease: 'linear'
            }
          }}
        >
          {looped.map((skill, i) => (
            <span
              key={i}
              className={`
                inline-block
                uppercase
                text-2xl md:text-3xl
                font-bold tracking-wider
                ${theme === 'dark'
                  ? 'text-yellow-200'
                  : 'text-blue-700'}
              `}
            >
              {skill}
            </span>
          ))}
        </motion.div>
      </div>
    </section>
  );
}
